internal object LocalShareWebApp {
    const val HTML="""<!doctype html><html><head><meta charset=utf-8><meta name=viewport content="width=device-width,initial-scale=1"><title>WizeFiles PC Access</title><style>:root{font:15px system-ui;color-scheme:light dark}body{margin:0;background:#f6f5fa;color:#211f26}header{display:flex;gap:.6rem;align-items:center;padding:1rem 1.4rem;background:#6750a4;color:white}header h1{font-size:1.2rem;margin:0 auto 0 0}.bar{display:flex;gap:.55rem;flex-wrap:wrap;padding:1rem 1.4rem}.crumbs{padding:0 1.4rem 1rem}.crumbs button{border:0;background:none;color:#6750a4}button,input,select{font:inherit;border-radius:12px;border:1px solid #aaa;padding:.6rem .8rem}button.primary{background:#6750a4;color:white;border:0}#items{margin:0 1.4rem 2rem;padding:0;display:grid;grid-template-columns:repeat(auto-fill,minmax(190px,1fr));gap:.7rem}#items.list{display:block}.item{list-style:none;background:white;border:1px solid #ddd;border-radius:16px;padding:1rem;cursor:default;overflow:hidden}.item.selected{outline:3px solid #6750a4}.item .icon{font-size:2rem}.item .name{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.list .item{display:flex;gap:1rem;border-radius:0}.drop{outline:4px dashed #6750a4}dialog{border:0;border-radius:20px;max-width:min(850px,90vw)}dialog img,dialog video,dialog iframe{max-width:80vw;max-height:75vh}#pair{max-width:420px;margin:10vh auto;padding:2rem;background:white;border-radius:24px;text-align:center}.pair-controls{display:flex;gap:.55rem;align-items:center;justify-content:center}@media(max-width:420px){.pair-controls{flex-direction:column;align-items:stretch}}.muted{color:#716b76}@media(prefers-color-scheme:dark){body{background:#151218;color:#eee}.item,#pair{background:#252129;border-color:#444}}</style></head><body><section id=pair><h2>Connect to WizeFiles</h2><p>Enter the pairing code shown on your phone.</p><div class=pair-controls><input id=code inputmode=numeric autocomplete=one-time-code maxlength=6><button class=primary id=connect>Connect</button></div><p class=muted>Trusted local networks only.</p></section><main hidden><header><h1>WizeFiles</h1><span id=status>Connected</span></header><div class=bar><select id=roots></select><input id=search placeholder="Search this shared folder"><select id=sort><option value=name>Name</option><option value=size>Size</option></select><button id=view>List / grid</button><button id=newFolder>New folder</button><label><input id=upload type=file multiple hidden><button type=button id=uploadButton>Upload files</button></label><label><input id=folderUpload type=file webkitdirectory multiple hidden><button type=button id=folderUploadButton>Upload folder</button></label><button id=download>Download</button><button class=destructive id=rename>Rename</button><button class=destructive id=move>Move</button><button id=copy>Copy</button><button class=destructive id=remove>Delete</button></div><nav class=crumbs id=crumbs></nav><ul id=items></ul></main><dialog id=preview><button onclick=preview.close()>Close</button><div id=previewBody></div></dialog><script>let csrf='',permission='',path='',entries=[],selected=new Set();const q=s=>document.querySelector(s),esc=s=>{let d=document.createElement('div');d.textContent=s;return d.innerHTML},api=(u,o={})=>fetch(u,{...o,headers:{...(o.headers||{}),'X-Wize-CSRF':csrf}});q('#connect').onclick=()=>pairWith('code',q('#code').value);async function pairWith(kind,value){let r=await fetch('/pair?'+kind+'='+encodeURIComponent(value),{method:'POST'});if(!r.ok)return alert('Pairing failed');let session=await r.json();csrf=session.csrf;permission=session.permission;q('#pair').hidden=true;if(permission!=='FULL_MANAGEMENT')document.querySelectorAll('.destructive').forEach(x=>x.hidden=true);q('main').hidden=false;let a=await(await fetch('/api/roots')).json();q('#roots').innerHTML=a.map(x=>'<option value="'+esc(x.id)+'">'+esc(x.name)+'</option>').join('');load('')}q('#roots').onchange=()=>load('');q('#sort').onchange=render;q('#view').onclick=()=>q('#items').classList.toggle('list');q('#search').oninput=async e=>{if(!e.target.value)return load(path);entries=await(await fetch('/api/search?root='+encodeURIComponent(q('#roots').value)+'&path='+encodeURIComponent(path)+'&q='+encodeURIComponent(e.target.value))).json();render()};async function load(p){path=p;selected.clear();entries=await(await fetch('/api/list?root='+encodeURIComponent(q('#roots').value)+'&path='+encodeURIComponent(path))).json();render();crumb()}function render(){let key=q('#sort').value;entries.sort((a,b)=>key==='size'?a.size-b.size:a.name.localeCompare(b.name));q('#items').innerHTML=entries.map((x,i)=>'<li class="item" data-i="'+i+'"><div class=icon>'+(x.directory?'📁':'📄')+'</div><div class=name>'+esc(x.name)+'</div><small>'+(!x.directory?format(x.size):'Folder')+'</small></li>').join('');document.querySelectorAll('.item').forEach(el=>{el.onclick=e=>{let n=entries[+el.dataset.i].name;if(e.ctrlKey||e.metaKey){selected.has(n)?selected.delete(n):selected.add(n);el.classList.toggle('selected')}else if(entries[+el.dataset.i].directory)load(join(path,n));else show(join(path,n))}})}function crumb(){let parts=path?path.split('/'):[];q('#crumbs').innerHTML='<button data-p="">Home</button>'+parts.map((x,i)=>' / <button data-p="'+esc(parts.slice(0,i+1).join('/'))+'">'+esc(x)+'</button>').join('');q('#crumbs').querySelectorAll('button').forEach(b=>b.onclick=()=>load(b.dataset.p))}q('#newFolder').onclick=async()=>{let n=prompt('Folder name');if(!n)return;let r=await api('/api/folder?root='+encodeURIComponent(q('#roots').value)+'&path='+encodeURIComponent(join(path,n)),{method:'POST'});if(!r.ok)alert(await r.text());else load(path)};q('#uploadButton').onclick=()=>q('#upload').click();q('#folderUploadButton').onclick=()=>q('#folderUpload').click();q('#upload').onchange=e=>uploadFiles([...e.target.files]);q('#folderUpload').onchange=e=>uploadFiles([...e.target.files]);document.body.ondragover=e=>{e.preventDefault();document.body.classList.add('drop')};document.body.ondragleave=()=>document.body.classList.remove('drop');document.body.ondrop=e=>{e.preventDefault();document.body.classList.remove('drop');uploadFiles([...e.dataTransfer.files])};async function uploadFiles(files){for(let f of files){let relative=join(path,f.webkitRelativePath||f.name),key='wize-upload:'+q('#roots').value+':'+relative+':'+f.size+':'+f.lastModified,saved=JSON.parse(localStorage.getItem(key)||'null'),offset=saved?.offset||0,id=saved?.id||'',chunk=4*1024*1024;while(offset<f.size||f.size===0&&offset===0){let body=f.slice(offset,Math.min(f.size,offset+chunk)),r=await api('/api/upload?root='+encodeURIComponent(q('#roots').value)+'&path='+encodeURIComponent(relative),{method:'PUT',body,headers:{'Upload-Length':f.size,'Upload-Offset':offset,...(id?{'Upload-Id':id}:{})}});if(!r.ok){alert('Upload paused and can be resumed by selecting the same file again: '+f.name);return}let state=await r.json();id=state.uploadId;offset=state.offset;localStorage.setItem(key,JSON.stringify({id,offset}));q('#status').textContent='Uploading '+f.name+' '+Math.round((offset/Math.max(1,f.size))*100)+'%';if(state.waitingForApproval){localStorage.removeItem(key);alert('Upload complete. Waiting for overwrite approval on your phone.');break}if(state.complete||f.size===0){localStorage.removeItem(key);break}}}q('#status').textContent='Connected';load(path)}q('#download').onclick=()=>{let names=[...selected];if(names.length>1)window.open('/api/zip?root='+encodeURIComponent(q('#roots').value)+'&paths='+encodeURIComponent(names.map(n=>join(path,n)).join('|')));else for(let n of names)window.open('/api/download?root='+encodeURIComponent(q('#roots').value)+'&path='+encodeURIComponent(join(path,n)))};q('#rename').onclick=async()=>{let n=[...selected][0],to=prompt('New name',n);if(n&&to)await action('rename',n,join(path,to))};q('#move').onclick=async()=>{let n=[...selected][0],to=prompt('Destination path',join(path,n));if(n&&to)await action('move',n,to)};q('#copy').onclick=async()=>{let n=[...selected][0],to=prompt('Copy destination path',join(path,n));if(n&&to){let r=await api('/api/copy?root='+encodeURIComponent(q('#roots').value)+'&path='+encodeURIComponent(join(path,n))+'&targetRoot='+encodeURIComponent(q('#roots').value)+'&targetPath='+encodeURIComponent(to),{method:'POST'});if(!r.ok)alert(await r.text());else load(path)}};q('#remove').onclick=async()=>{for(let n of selected)await action('delete',n,'')};async function action(type,n,to){let r=await api('/api/action?type='+type+'&root='+encodeURIComponent(q('#roots').value)+'&path='+encodeURIComponent(join(path,n))+'&targetRoot='+encodeURIComponent(q('#roots').value)+'&targetPath='+encodeURIComponent(to),{method:'POST'});let state=await r.json();alert(state.state==='waiting_for_phone'?'Waiting for approval on your phone':'Operation completed');if(state.state==='completed')load(path)};function show(p){q('#previewBody').innerHTML='<iframe src="/api/preview?root='+encodeURIComponent(q('#roots').value)+'&path='+encodeURIComponent(p)+'"></iframe>';q('#preview').showModal()}function join(a,b){return a?a+'/'+b:b}function format(n){return n<1024?n+' B':n<1048576?(n/1024).toFixed(1)+' KB':(n/1048576).toFixed(1)+' MB'}document.onkeydown=e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='a'){e.preventDefault();entries.forEach(x=>selected.add(x.name));render()}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='u'){e.preventDefault();q('#upload').click()}if(e.key==='Delete'&&!q('#remove').hidden)q('#remove').click();if(e.key==='F2'&&!q('#rename').hidden)q('#rename').click()};let token=new URLSearchParams(location.search).get('token');if(token){history.replaceState({},'',location.pathname);pairWith('token',token)}</script></body></html>"""
